tool_calls:
cd /home/eval/inventory && python3 - <<'PY'
p='lib/inventory.sh'
s=open(p).read()
a=s.index('  local sku name qty price')
b=s.index('\n}\n',a)
s=s[:a]+'''  local line sku qty price fields
  {
    read -r _header
    while IFS= read -r line || [[ -n $line ]]; do
      line=${line%$'\\r'}
      # The name may contain quoted commas; extract the numeric columns
      # from the right and the SKU from the left without splitting the name.
      sku=${line%%,*}
      price=${line##*,}
      fields=${line%,*}
      qty=${fields##*,}
      printf '%s %s %s\\n' "$sku" "$qty" "$price"
    done
  } < "$1"'''+s[b:]
open(p,'w').write(s)
PY
make test

